import { Table, BooleanColumn, StringColumn, ReferenceColumn } from '../../db'

export const sys_ui_annotation = Table({
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
        no_audit_delete: true,
    },
    label: 'Form Annotation',
    name: 'sys_ui_annotation',
    schema: {
        is_plain_text: BooleanColumn({
            default: true,
            label: 'Is plain text',
        }),

        text: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_truncate: true,
            },
            label: 'Text',
            maxLength: 4000,
        }),

        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_truncate: true,
            },
            label: [
                {
                    hint: 'Unique identifier to use with Client Script API: g_form.getAnnotationByName()',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            maxLength: 100,
        }),

        type: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Type',
            referenceTable: 'sys_ui_annotation_type',
        }),
    },
})
